/* 发布护航台 RunGuard — runbook 数据（内联，随首屏就绪，无异步取数） */
var RUNBOOK = {
  id: "rb-pay-2410",
  code: "CHG-2026-1024",
  title: "支付服务 v2.4.1 生产发布",
  risk: "高后果 · 含 3 个不可逆操作",
  win: "发布窗口 22:00–23:30",
  phases: [
    {
      id: "p1",
      name: "阶段一 · 预检",
      goal: "确认今晚具备发布条件；任何一项不满足都应停下来，而不是带病放行。",
      steps: [
        {
          id: "s1",
          title: "确认发布窗口与值守",
          why: "发布窗口冲突或值守缺位时，出现异常将无人处置——这是后面一切步骤的安全前提。",
          checks: [
            "变更单 CHG-2026-1024 已登记并获审批通过",
            "值守发布负责人与回滚执行人已到位并互相确认",
            "发布窗口（22:00–23:30）内无其他高优先级变更并行"
          ]
        },
        {
          id: "s2",
          title: "观测基线检查",
          why: "基线不干净时，发布后无法区分「新问题」与「旧问题」，会延误回滚决策。",
          checks: [
            "核心支付大盘无进行中的告警",
            "当前错误率基线 0.03%，低于 0.10% 门槛",
            "发布看板已投屏，回滚手册已置于手边"
          ]
        },
        {
          id: "s3",
          title: "发布产物核验",
          why: "上生产的镜像必须与测试过的产物完全一致；核验是防呆的最后一道机会。",
          checks: [
            "CI 流水线 #8841 绿色，产物即 pay-service:v2.4.1",
            "镜像安全扫描无高危漏洞，签名校验通过"
          ],
          verify: {
            question: "预检是否全部通过，可以进入灰度发布？",
            passLabel: "全部通过，进入灰度",
            failLabel: "存在问题，进入异常处理"
          }
        }
      ]
    },
    {
      id: "p2",
      name: "阶段二 · 灰度发布",
      goal: "用最小爆炸半径先验证新版本；此阶段尚未发生任何不可逆变更。",
      steps: [
        {
          id: "s4",
          title: "部署灰度实例",
          why: "灰度是高后果流程的「可逆试验田」：出了问题直接缩容即可，不触碰数据。",
          checks: [
            "按滚动策略将 5% 实例升级至 v2.4.1",
            "灰度实例全部就绪并已纳入发布看板"
          ]
        },
        {
          id: "s5",
          title: "灰度验证",
          why: "只有灰度达标才允许触碰数据库与全量流量；不达标继续放行，等于把风险推进不可逆区。",
          checks: [
            "灰度运行满 15 分钟",
            "变更单已回填灰度观测记录"
          ],
          verify: {
            question: "灰度验证：支付成功率 ≥ 99.95% 且 P99 ≤ 300ms，是否达标？",
            passLabel: "达标，进入数据迁移",
            failLabel: "未达标，进入异常处理"
          }
        }
      ]
    },
    {
      id: "p3",
      name: "阶段三 · 数据迁移",
      goal: "不可逆区开始：一切动作以「先备好恢复路径」为前提。",
      steps: [
        {
          id: "s6",
          title: "数据库快照与备份",
          why: "快照是下一个不可逆操作的唯一恢复路径——没有它，迁移失败将无法回退。",
          checks: [
            "已对 orders / payments 库完成全量快照 snap-1024-pay",
            "快照校验和比对一致",
            "已在沙箱演练一次快照恢复路径"
          ]
        },
        {
          id: "s7",
          title: "执行数据库迁移",
          why: "schema 变更没有「撤销」按钮，只有恢复预案；请逐条读完后果再确认。",
          checks: [
            "已再次确认快照 snap-1024-pay 可用",
            "已通知值班群：数据库进入只读迁移窗口"
          ],
          irrev: {
            code: "MIGRATE-2410",
            headline: "对 orders 表执行迁移 20261024_split_refund_state（新增 refund_state_v2 列并回填、移除旧状态位）。",
            consequences: [
              "表结构永久变更：旧版本 v2.3.9 将无法写入新列",
              "迁移期间订单库只读，预计 4 分钟",
              "回滚只能依赖快照恢复，预计停机约 25 分钟"
            ],
            recovery: {
              title: "快照回滚",
              steps: [
                "宣布停机，摘除全部应用流量",
                "从 snap-1024-pay 恢复 orders / payments 库",
                "校验数据一致性后恢复流量",
                "在变更单记录实际 RTO"
              ]
            }
          }
        },
        {
          id: "s8",
          title: "迁移后数据校验",
          why: "迁移完成不等于迁移正确；数据校验通过之前，不允许切换全量流量。",
          verify: {
            question: "抽样 1000 笔订单：refund_state_v2 回填率 100%、主业务读写正常，是否通过？",
            passLabel: "校验通过，进入全量切换",
            failLabel: "校验不通过，进入异常处理"
          }
        }
      ]
    },
    {
      id: "p4",
      name: "阶段四 · 全量切换",
      goal: "流量与新库绑定之后，回退窗口开始收窄。",
      steps: [
        {
          id: "s9",
          title: "全量切换流量",
          why: "这一步之后，全部用户都在新版本上；任何缺陷都直接面对全量交易。",
          checks: [
            "已确认迁移后校验记录在案",
            "已通知客服与值班群：即将全量切换"
          ],
          irrev: {
            code: "CUTOVER-2410",
            headline: "将 100% 生产流量从 v2.3.9 切至 v2.4.1，并缩容旧版本实例池至 0。",
            consequences: [
              "全部用户立即使用新版本，缺陷直接影响全量交易",
              "旧实例池缩容后重新拉起需约 8 分钟",
              "回滚期间成功率会再次抖动，需要二次公告"
            ],
            recovery: {
              title: "流量切回",
              steps: [
                "网关 100% 切回 v2.3.9 旧池",
                "重新拉起旧版本实例并等待就绪",
                "确认成功率回升至基线",
                "记录切回时刻与原因"
              ]
            }
          }
        },
        {
          id: "s10",
          title: "全量观察",
          why: "全量后的第一段观察决定是否需要立即执行「流量切回」。",
          checks: [
            "全量后 15 分钟核心指标与基线持平",
            "无资损类告警，支付链路对账正常"
          ],
          verify: {
            question: "全量观察是否通过，可以进入收尾？",
            passLabel: "通过，进入收尾",
            failLabel: "未通过，进入异常处理"
          }
        }
      ]
    },
    {
      id: "p5",
      name: "阶段五 · 收尾",
      goal: "关闭发布窗口；把回退能力归档，而不是遗忘。",
      steps: [
        {
          id: "s11",
          title: "旧版本下线",
          why: "下线即关闭快速回滚窗口；确认监控稳定后再做，且归档是最后的恢复路径。",
          checks: [
            "全量稳定运行满 30 分钟",
            "已确认镜像归档仓库可访问"
          ],
          irrev: {
            code: "RETIRE-239",
            headline: "删除 v2.3.9 生产镜像与旧配置，释放发布占用的集群资源。",
            consequences: [
              "旧版本从生产环境永久移除，快速回滚窗口关闭",
              "如需回退只能从归档重建，预计约 40 分钟",
              "集群缩容产生的成本节省立即生效"
            ],
            recovery: {
              title: "归档重建",
              steps: [
                "从归档仓库拉取 pay-service:v2.3.9",
                "按归档配置重建旧版本实例池",
                "切回流量并验证",
                "在变更单记录重建耗时"
              ]
            }
          }
        },
        {
          id: "s12",
          title: "发布宣告与归档",
          why: "记录是零失误的最后一环：完整归档让下一次发布站在本次的证据之上。",
          checks: [
            "已在值班频道宣告 v2.4.1 发布完成",
            "变更单关闭，观测截图归档",
            "审计日志已导出并附至变更单"
          ]
        }
      ]
    }
  ]
};

