  function actComplete(id) {
    var s = stepById(id);
    if (!checksDone(s)) return;
    st(id).status = "done";
    addEvent("step", "完成步骤：" + s.title);
    state.viewedStepId = null;
    finishFlowIfLast();
    save(); render();
