  function kindBadge(s) {
    if (s.irrev) return '<span class="chip chip-danger">不可逆操作</span>';
    if (s.verify) return '<span class="chip chip-warn">验证门</span>';
    return '<span class="chip">检查项</span>';
  }
  function renderStepCard(s, readonly) {
    var i = STEPS.indexOf(s);
    var ss = st(s.id);
    var done = ss.checks.filter(function (b) { return b; }).length;
    var total = (s.checks || []).length;
    var html = '<section class="card step-card' + (s.irrev ? " step-irrev" : "") + '">';
    html += '<div class="eyebrow">' + esc(s._phase.name) + ' · 第 ' + (i + 1) + ' / ' + STEPS.length + ' 步 ' + kindBadge(s) + '</div>';
    html += '<h2>' + esc(s.title) + '</h2>';
    if (readonly) {
      var label = ss.status === "rolled_back" ? "已回滚" : "已完成";
      html += '<div class="review-note"><span class="chip ' + (ss.status === "rolled_back" ? "chip-warn" : "chip-ok") + '">' + label + ' · 只读回看</span> <button class="btn btn-ghost btn-sm" data-action="back-current">返回当前步骤</button></div>';
      if (ss.status === "rolled_back") html += '<div class="why">该不可逆操作已按恢复预案回滚，流程转入安全中止。</div>';
    } else {
      html += '<div class="why"><strong>为什么重要</strong>' + esc(s.why || "") + '</div>';
    }
    if (s.checks) {
      html += '<div class="check-head"><span>执行确认项</span><span class="count">' + done + ' / ' + total + '</span></div>';
      html += '<div class="checks">' + s.checks.map(function (c, ci) {
        var checked = ss.checks[ci];
        if (readonly) {
          return '<div class="check-row static"><span class="ro-ico">' + (checked ? "✓" : "○") + '</span><span>' + esc(c) + '</span></div>';
        }
        return '<label class="check-row"><input type="checkbox" class="cbx" data-check data-step="' + s.id + '" data-i="' + ci + '"' + (checked ? " checked" : "") + '><span>' + esc(c) + '</span></label>';
      }).join("") + "</div>";
    }
    if (s.irrev) {
      html += renderIrrevBlock(s, readonly, checksDone(s));
    } else if (s.verify && !readonly) {
      html += renderVerifyBlock(s, checksDone(s));
    }
    // normal complete button
    if (!s.verify && !s.irrev && !readonly) {
      html += '<div class="actions"><button class="btn btn-primary" data-action="complete" data-step="' + s.id + '"' + (checksDone(s) ? "" : " disabled") + '>完成步骤，继续 →</button>' +
        (checksDone(s) ? "" : '<span class="hint">还剩 ' + (total - done) + ' 项确认未完成</span>') + "</div>";
    }
    if (state.mode === "deviation" && !readonly && st(s.id).verify === "fail") {
