.panel-head { padding: 11px 16px; font-weight: 700; border-bottom: 1px solid var(--line); display: flex; align-items: center; gap: 8px; }
.panel-body { padding: 12px 14px; }
.empty { color: var(--mut); font-size: 13px; text-align: center; padding: 14px 6px; }
.rec-item { border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; margin-bottom: 10px; }
.rec-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.rec-t { font-weight: 600; font-size: 13.5px; }
.rec-meta { font-size: 12px; color: var(--mut); margin: 3px 0 8px; font-variant-numeric: tabular-nums; }
.events { list-style: none; padding: 6px 14px 10px; max-height: 44vh; overflow-y: auto; }
.events li { display: flex; gap: 9px; padding: 6px 0; border-bottom: 1px dashed #edf0f4; font-size: 12.5px; align-items: baseline; }
.events li:last-child { border-bottom: none; }
.ev-t { color: var(--mut); font-variant-numeric: tabular-nums; white-space: nowrap; flex: none; }
.ev-x { color: #35404f; }

