.modal { width: 620px; max-width: 94vw; max-height: 88vh; overflow-y: auto; background: var(--panel); border-radius: 14px; padding: 24px 26px; box-shadow: 0 18px 50px rgba(9, 14, 24, .35); border-top: 3px solid var(--danger); }
.modal-sm { width: 460px; border-top: 3px solid var(--warn-line); }
.modal h3 { font-size: 18px; margin-bottom: 10px; }
.code-label { display: block; font-weight: 600; margin: 16px 0 8px; }
.code-label code { background: var(--danger-bg); color: var(--danger); border: 1px solid var(--danger-line); border-radius: 6px; padding: 1px 8px; font-size: 13.5px; }
.code-input { width: 100%; padding: 10px 12px; font-size: 16px; letter-spacing: 1px; border: 1.5px solid var(--line-strong); border-radius: 8px; font-family: Consolas, monospace; }
.code-input:focus { border-color: var(--accent); outline: none; }

