class MiniWS {
  constructor(url) { this.url = url; this._buf = Buffer.alloc(0); this._frag = []; this.onmessage=null; this.onopen=null; this.onclose=null; }
  connect() {
    return new Promise((resolve, reject) => {
      const u = new URL(this.url);
      this._sock = net.connect(+u.port, u.hostname, () => {
        const key = crypto.randomBytes(16).toString("base64");
        const req = "GET " + u.pathname + " HTTP/1.1\r\nHost: " + u.host + "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: " + key + "\r\nSec-WebSocket-Version: 13\r\n\r\n";
        this._sock.write(req);
      });
      let handshook = false;
      this._sock.on("data", (d) => {
        this._buf = Buffer.concat([this._buf, d]);
        if (!handshook) {
          const idx = this._buf.indexOf("\r\n\r\n");
          if (idx === -1) return;
          const head = this._buf.slice(0, idx).toString();
          if (!/ 101 /.test(head.split("\r\n")[0])) { reject(new Error("ws handshake failed: " + head.split("\r\n")[0])); return; }
          this._buf = this._buf.slice(idx + 4);
          handshook = true; resolve();
        }
        this._drainFrames();
      });
      this._sock.on("error", reject);
      this._sock.on("close", () => { if (this.onclose) this.onclose(); });
    });
  }
  _drainFrames() {
    for (;;) {
      const b = this._buf;
      if (b.length < 2) return;
      const fin = (b[0] & 0x80) !== 0;
      const op = b[0] & 0x0f;
      const masked = (b[1] & 0x80) !== 0;
      let len = b[1] & 0x7f;
      let off = 2;
      if (len === 126) { if (b.length < 4) return; len = b.readUInt16BE(2); off = 4; }
      else if (len === 127) { if (b.length < 10) return; len = Number(b.readBigUInt64BE(2)); off = 10; }
      if (masked) off += 4;
      if (b.length < off + len) return;
      let payload = b.slice(off, off + len);
      if (masked) { const mask = b.slice(off - 4, off); for (let i = 0; i < payload.length; i++) payload[i] ^= mask[i & 3]; }
      this._buf = b.slice(off + len);
      if (op === 8) { try { this._sock.end(); } catch (e) {} if (this.onclose) this.onclose(); return; }
      if (op === 9) { this._sendFrame(10, payload); continue; }
      if (op === 1 || op === 2 || op === 0) {
        this._frag.push(payload);
        if (fin) { const full = Buffer.concat(this._frag).toString("utf8"); this._frag = []; if (this.onmessage) this.onmessage(full); }
      }
    }
  }
  send(text) { this._sendFrame(1, Buffer.from(text, "utf8")); }
  _sendFrame(op, payload) {
    const mask = crypto.randomBytes(4);
    const len = payload.length;
    let head;
    if (len < 126) head = Buffer.from([0x80 | op, 0x80 | len]);
    else if (len < 65536) { head = Buffer.alloc(4); head[0] = 0x80 | op; head[1] = 0x80 | 126; head.writeUInt16BE(len, 2); }
    else { head = Buffer.alloc(10); head[0] = 0x80 | op; head[1] = 0x80 | 127; head.writeBigUInt64BE(BigInt(len), 2); }
    const masked = Buffer.from(payload);
    for (let i = 0; i < masked.length; i++) masked[i] ^= mask[i & 3];
    this._sock.write(Buffer.concat([head, mask, masked]));
  }
}
