25	class MiniWS {
26	  constructor(url) { this.url = url; this._buf = Buffer.alloc(0); this._frag = []; this.onmessage = null; this.onclose = null; }
27	  connect() {
28	    return new Promise((resolve, reject) => {
29	      const u = new URL(this.url);
30	      this._sock = net.connect(+u.port, u.hostname, () => {
31	        const key = crypto.randomBytes(16).toString("base64");
32	        this._sock.write(
33	          "GET " + u.pathname + " HTTP/1.1\r\nHost: " + u.host + "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n" +
34	          "Sec-WebSocket-Key: " + key + "\r\nSec-WebSocket-Version: 13\r\n\r\n");
35	      });
36	      let handshook = false;
37	      this._sock.on("data", (d) => {
38	        this._buf = Buffer.concat([this._buf, d]);
39	        if (!handshook) {
40	          const idx = this._buf.indexOf("\r\n\r\n");
41	          if (idx === -1) return;
42	          const first = this._buf.slice(0, idx).toString().split("\r\n")[0];
43	          if (!/ 101 /.test(first)) { reject(new Error("ws handshake failed: " + first)); return; }
44	          this._buf = this._buf.slice(idx + 4);
45	          handshook = true; resolve();
46	        }
47	        this._drain();
48	      });
49	      this._sock.on("error", (e) => { if (!handshook) reject(e); });
50	      this._sock.on("close", () => { if (this.onclose) this.onclose(); });
51	    });
52	  }
53	  _drain() {
54	    for (;;) {
55	      const b = this._buf;
56	      if (b.length < 2) return;
57	      const fin = (b[0] & 0x80) !== 0, op = b[0] & 0x0f;
58	      let len = b[1] & 0x7f, off = 2;
59	      if (len === 126) { if (b.length < 4) return; len = b.readUInt16BE(2); off = 4; }
60	      else if (len === 127) { if (b.length < 10) return; len = Number(b.readBigUInt64BE(2)); off = 10; }

